import numpy as np

def R(x, z):
    return ((2*x**2 + 1)**2 * (2*z**2 + 1)) / (x**2 + 2*x*z)

# Test the range x, z in [0.1, 1.0]
x_vals = np.linspace(0.1, 1.0, 100)
z_vals = np.linspace(0.1, 1.0, 100)

min_ratio = float('inf')
for x in x_vals:
    for z in z_vals:
        ratio = R(x, z)
        if ratio < min_ratio:
            min_ratio = ratio

print(f"Minimum ratio found in [0.1, 1.0]: {min_ratio}")
